using System.Text;
namespace SoloCamera.Windows;
public static class QrIntegrationTest {
 public static async Task Run(string codeFile,string report){using var camera=new PhoneConnection();var found=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);using var pairing=new QrPairing((host,key)=>{camera.Connect(host,key);found.TrySetResult(true);});string address=Environment.GetEnvironmentVariable("SOLO_QA_HOST")??QrPairing.Addresses().First();await File.WriteAllTextAsync(codeFile,pairing.Code(address),new UTF8Encoding(false));await File.WriteAllTextAsync(report,"Ready to scan");try{await found.Task.WaitAsync(TimeSpan.FromSeconds(110));await File.WriteAllTextAsync(report,"PASS Encrypted QR registration from Android; awaiting camera approval");for(int i=0;i<450&&camera.Frames<30;i++){await Task.Delay(100);if(!camera.Running)throw new Exception(camera.Status);}if(!camera.Status.Contains("low latency"))throw new Exception("Live preview negotiation failed: "+camera.Status);if(camera.Frames<30)throw new Exception("Preview not received: "+camera.Status);using var server=new LocalFeedServer(new[]{camera});using var http=new HttpClient();long previous=camera.Latest!.Sequence;var response=await http.GetAsync(server.Url.Replace("/feed","/frame/0")+"?after="+previous);if(!response.IsSuccessStatusCode||!long.TryParse(response.Headers.GetValues("X-Sequence").First(),out long next)||next<=previous)throw new Exception("OBS long-poll did not deliver a fresh frame");long before=camera.Frames;await Task.Delay(5000);if(camera.Frames-before<10)throw new Exception("Stream stalled");await File.WriteAllTextAsync(report,$"PASS Encrypted QR registration from Android over LAN\nPASS Live preview after QR pairing: {camera.Frames-before} frames in 5 seconds\n");camera.Disconnect();await camera.WaitStopped();if(camera.Latest!=null)throw new Exception("Stale image");await File.AppendAllTextAsync(report,"PASS Disconnect clears camera frame\n");}catch(Exception e){await File.AppendAllTextAsync(report,"\nFAIL "+e.Message);}finally{File.Delete(codeFile);}}
}



